steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{
      issue(identifier: \"ENG-9\") {
        id
        identifier
        title
        team {
          id
          name
        }
      }
      teams(filter: { name: { eq: \"Engineering\" } }) {
        nodes {
          id
          name
          cycles {
            nodes {
              id
              name
              number
            }
          }
        }
      }
    }"
  }'
